 **C++ Implementation**
 ```cpp
 int computePrefixFunction(const std::string& pattern) {
   int n = pattern.length();
   std::vector<int> prefix(n);
   prefix[0] = 0;
   int k = 0;
   for (int i = 1; i < n; ++i) {
       while (k > 0 && pattern[k]!= pattern[i]) {
           k = prefix[k - 1];
       }
       if (pattern[k] == pattern[i]) {
           k += 1;
       }
       prefix[i] = k;
   }
   return prefix[n - 1];
 }

 bool knuthMorrisPratt(const std::string& text, const std::string& pattern) {
   int prefix = computePrefixFunction(pattern);
   int textLength = text.length();
   int patternLength = pattern.length();
   int i = 0;
   while (i < textLength) {
       int j = 0;
       while (j < patternLength && text[i] == pattern[j]) {
           i += 1;
           j += 1;
       }
       if (j == 0) {
           i += 1;
       } else if (j > prefix) {
           j = prefix + (j - prefix - 1);
       } else {
           j = 0;
       }
   }
   return i >= textLength;
 }
